function build(opts){ opts=opts||{};
  var x=Number(opts.x==null?0:opts.x), y=Number(opts.y==null?0:opts.y), blur=Number(opts.blur==null?0:opts.blur), spread=Number(opts.spread==null?0:opts.spread);
  if([x,y,blur,spread].some(function(v){return isNaN(v);})) return {error:'数值无效'};
  if(blur<0) return {error:'blur 不能为负'};
  var color=opts.color||'#000000'; var inset=opts.inset?'inset ':'';
  return {css:inset+x+'px '+y+'px '+blur+'px '+spread+'px '+color}; }
function layers(list){ return list.map(function(o){var r=build(o); if(r.error) return r.error; return r.css;}).join(', '); }
var EXPORTS={build:build, layers:layers};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BoxShadowForgePure = EXPORTS; }
